const o=[{id:"obstetrics-gynecology-001",topicId:"obstetrics-gynecology",question:"Чем занимается акушерство?",options:["Лечением бесплодия у мужчин","Заболеваниями мочевыделительной системы","Здоровьем женской репродуктивной системы вне беременности","Уходом за беременными женщинами и родоразрешением"],correctIndex:3,explanation:"Акушерство занимается уходом за беременными женщинами и родоразрешением.",difficulty:"easy",tags:["определения"]},{id:"obstetrics-gynecology-002",topicId:"obstetrics-gynecology",question:"На чём фокусируется гинекология?",options:["На родоразрешении","На здоровье женской репродуктивной системы вне беременности","На заболеваниях молочных желёз у мужчин","На послеродовом уходе за новорождённым"],correctIndex:1,explanation:"Гинекология фокусируется на здоровье женской репродуктивной системы вне беременности.",difficulty:"easy",tags:["определения"]},{id:"obstetrics-gynecology-003",topicId:"obstetrics-gynecology",question:"Как называются наружные женские половые органы?",options:["Вульва","Эндометрий","Периметрий","Миометрий"],correctIndex:0,explanation:"Наружные органы — вульва: лобок, большие и малые половые губы, клитор, преддверие влагалища.",difficulty:"easy",tags:["анатомия"]},{id:"obstetrics-gynecology-004",topicId:"obstetrics-gynecology",question:"Что открывается в преддверие влагалища?",options:["Маточные трубы","Прямая кишка","Влагалище и мочеиспускательный канал","Шейка матки и яичники"],correctIndex:2,explanation:"Преддверие влагалища — пространство между малыми половыми губами, куда открываются влагалище и мочеиспускательный канал.",difficulty:"medium",tags:["анатомия"]},{id:"obstetrics-gynecology-005",topicId:"obstetrics-gynecology",question:"Какую функцию выполняют большие и малые половые губы?",options:["Служат местом оплодотворения","Вырабатывают эстрогены","Образуют жёлтое тело","Защищают вход во влагалище"],correctIndex:3,explanation:"Большие и малые половые губы — кожные складки, защищающие вход во влагалище.",difficulty:"medium",tags:["анатомия"]},{id:"obstetrics-gynecology-006",topicId:"obstetrics-gynecology",question:"Где располагаются внутренние женские половые органы?",options:["В паховом канале","В брюшной полости над пупком","В забрюшинном пространстве","В полости малого таза"],correctIndex:3,explanation:"Внутренние половые органы располагаются в полости малого таза.",difficulty:"easy",tags:["анатомия"]},{id:"obstetrics-gynecology-007",topicId:"obstetrics-gynecology",question:"Какие гормоны вырабатываются в яичниках?",options:["Пролактин и окситоцин","Эстрогены и прогестерон","ФСГ и ЛГ","Тестостерон и кортизол"],correctIndex:1,explanation:"Яичники — парные половые железы, где созревают яйцеклетки и вырабатываются эстрогены и прогестерон.",difficulty:"easy",tags:["анатомия","гормоны"]},{id:"obstetrics-gynecology-008",topicId:"obstetrics-gynecology",question:"Где обычно происходит оплодотворение?",options:["В яичнике","Во влагалище","В маточных (фаллопиевых) трубах","В полости матки"],correctIndex:2,explanation:"Маточные трубы соединяют матку с брюшной полостью рядом с яичниками; именно здесь обычно происходит оплодотворение.",difficulty:"medium",tags:["анатомия","физиология"]},{id:"obstetrics-gynecology-009",topicId:"obstetrics-gynecology",question:"Что представляет собой матка?",options:["Кожную складку","Полый мышечный орган для развития эмбриона и плода","Мышечную трубку, соединяющую матку с внешней средой","Парную половую железу"],correctIndex:1,explanation:"Матка — полый мышечный орган, предназначенный для развития эмбриона и плода; состоит из тела и шейки.",difficulty:"easy",tags:["анатомия"]},{id:"obstetrics-gynecology-010",topicId:"obstetrics-gynecology",question:"Из каких частей состоит матка?",options:["Из тела и шейки","Из двух долей и перешейка","Из коркового и мозгового слоя","Из головки, тела и хвоста"],correctIndex:0,explanation:"Матка состоит из тела и шейки.",difficulty:"easy",tags:["анатомия"]},{id:"obstetrics-gynecology-011",topicId:"obstetrics-gynecology",question:"Как называется внутренний слой стенки матки?",options:["Перитонеум","Эндометрий","Миометрий","Периметрий"],correctIndex:1,explanation:"Эндометрий — внутренний слой, слизистая оболочка, выстилающая полость матки.",difficulty:"easy",tags:["анатомия","матка"]},{id:"obstetrics-gynecology-012",topicId:"obstetrics-gynecology",question:"Какой слой стенки матки является средним?",options:["Базальный слой","Эндометрий","Миометрий","Периметрий"],correctIndex:2,explanation:"Стенка матки: эндометрий (внутренний), миометрий (средний), периметрий (наружный).",difficulty:"medium",tags:["анатомия","матка"]},{id:"obstetrics-gynecology-013",topicId:"obstetrics-gynecology",question:"Какой слой эндометрия отторгается во время менструации?",options:["Периметрий","Функциональный","Миометрий","Базальный"],correctIndex:1,explanation:"Функциональный слой эндометрия отторгается во время менструации, если не произошло оплодотворение.",difficulty:"medium",tags:["анатомия","матка"]},{id:"obstetrics-gynecology-014",topicId:"obstetrics-gynecology",question:"Какова средняя продолжительность менструального цикла?",options:["28 дней","7 дней","14 дней","40 дней"],correctIndex:0,explanation:"В среднем менструальный цикл длится 28 дней.",difficulty:"easy",tags:["менструальный цикл"]},{id:"obstetrics-gynecology-015",topicId:"obstetrics-gynecology",question:"Какой диапазон длительности менструального цикла считается нормой?",options:["От 14 до 21 дня","От 21 до 35 дней","От 35 до 45 дней","Ровно 28 дней"],correctIndex:1,explanation:"Нормой считается диапазон от 21 до 35 дней.",difficulty:"medium",tags:["менструальный цикл","нормы"]},{id:"obstetrics-gynecology-016",topicId:"obstetrics-gynecology",question:"Какова нормальная длительность менструации?",options:["3–7 дней","8–10 дней","1–2 дня","14 дней"],correctIndex:0,explanation:"Норма менструации: длительность 3–7 дней, объём до 80 мл, без крупных сгустков.",difficulty:"medium",tags:["менструальный цикл","нормы"]},{id:"obstetrics-gynecology-017",topicId:"obstetrics-gynecology",question:"Какой объём менструальной кровопотери считается нормой?",options:["До 20 мл","До 500 мл","До 80 мл","До 300 мл"],correctIndex:2,explanation:"Нормальный объём менструации — до 80 мл.",difficulty:"hard",tags:["менструальный цикл","нормы"]},{id:"obstetrics-gynecology-018",topicId:"obstetrics-gynecology",question:"Сколько фаз выделяют в менструальном цикле?",options:["5","4","2","3"],correctIndex:1,explanation:"Менструальный цикл делится на 4 фазы: менструальную, фолликулярную, овуляторную и лютеиновую.",difficulty:"easy",tags:["менструальный цикл"]},{id:"obstetrics-gynecology-019",topicId:"obstetrics-gynecology",question:"Что происходит в менструальную фазу?",options:["Разрыв доминантного фолликула","Образование жёлтого тела","Пик лютеинизирующего гормона","Отторжение эндометрия и снижение уровня эстрогенов и прогестерона"],correctIndex:3,explanation:"В менструальную фазу (1–5 день) происходит отторжение эндометрия, снижается уровень эстрогенов и прогестерона.",difficulty:"medium",tags:["менструальный цикл"]},{id:"obstetrics-gynecology-020",topicId:"obstetrics-gynecology",question:"Под действием какого гормона в фолликулярной фазе растёт фолликул?",options:["Прогестерона","ФСГ","ЛГ","Пролактина"],correctIndex:1,explanation:"В фолликулярной (пролиферативной) фазе в яичнике под действием ФСГ растёт фолликул.",difficulty:"medium",tags:["менструальный цикл","гормоны"]},{id:"obstetrics-gynecology-021",topicId:"obstetrics-gynecology",question:"Что происходит с эндометрием в фолликулярной фазе?",options:["Отторгается","Утолщается и восстанавливается","Становится рыхлым и готовым к имплантации","Не изменяется"],correctIndex:1,explanation:"В фолликулярной фазе повышается уровень эстрогенов, эндометрий утолщается и восстанавливается.",difficulty:"medium",tags:["менструальный цикл"]},{id:"obstetrics-gynecology-022",topicId:"obstetrics-gynecology",question:"На какой день цикла примерно происходит овуляция при 28-дневном цикле?",options:["На 28 день","На 1 день","На 14 день","На 21 день"],correctIndex:2,explanation:"Овуляторная фаза — примерно 14 день при цикле 28 дней.",difficulty:"easy",tags:["менструальный цикл"]},{id:"obstetrics-gynecology-023",topicId:"obstetrics-gynecology",question:"Под действием пика какого гормона происходит разрыв доминантного фолликула?",options:["ФСГ","ЛГ","Окситоцина","Прогестерона"],correctIndex:1,explanation:"Под действием пика ЛГ происходит разрыв доминантного фолликула и выход яйцеклетки — овуляция.",difficulty:"medium",tags:["менструальный цикл","гормоны"]},{id:"obstetrics-gynecology-024",topicId:"obstetrics-gynecology",question:"Что образуется на месте лопнувшего фолликула в лютеиновой фазе?",options:["Полип эндометрия","Жёлтое тело","Новый фолликул","Киста яичника"],correctIndex:1,explanation:"В лютеиновой (секреторной) фазе на месте фолликула образуется жёлтое тело, вырабатывающее прогестерон.",difficulty:"medium",tags:["менструальный цикл"]},{id:"obstetrics-gynecology-025",topicId:"obstetrics-gynecology",question:"Какой гормон вырабатывает жёлтое тело?",options:["Окситоцин","ФСГ","Пролактин","Прогестерон"],correctIndex:3,explanation:"Жёлтое тело вырабатывает прогестерон; эндометрий становится рыхлым и готовым к имплантации.",difficulty:"medium",tags:["менструальный цикл","гормоны"]},{id:"obstetrics-gynecology-026",topicId:"obstetrics-gynecology",question:"Как называется воспаление слизистой оболочки влагалища?",options:["Вагинит (кольпит)","Эндометрит","Цервицит","Аднексит"],correctIndex:0,explanation:"Вагинит, кольпит — воспаление слизистой оболочки влагалища.",difficulty:"easy",tags:["заболевания","воспалительные"]},{id:"obstetrics-gynecology-027",topicId:"obstetrics-gynecology",question:"Что такое цервицит?",options:["Воспаление яичников","Воспаление влагалища","Воспаление эндометрия","Воспаление шейки матки"],correctIndex:3,explanation:"Цервицит — воспаление шейки матки.",difficulty:"medium",tags:["заболевания","воспалительные"]},{id:"obstetrics-gynecology-028",topicId:"obstetrics-gynecology",question:"Как называется воспаление яичников и маточных труб?",options:["Цервицит","Оофорит","Эндометрит","Сальпингоофорит (аднексит)"],correctIndex:3,explanation:"Сальпингоофорит (аднексит) — воспаление яичников и труб; оофорит — воспаление яичников.",difficulty:"medium",tags:["заболевания","воспалительные"]},{id:"obstetrics-gynecology-029",topicId:"obstetrics-gynecology",question:"Какой возбудитель вызывает хламидиоз?",options:["Neisseria gonorrhoeae","Chlamydia trachomatis","Candida albicans","Trichomonas vaginalis"],correctIndex:1,explanation:"Chlamydia trachomatis — возбудитель хламидиоза.",difficulty:"medium",tags:["заболевания","ИППП"]},{id:"obstetrics-gynecology-030",topicId:"obstetrics-gynecology",question:"Какое заболевание вызывает Neisseria gonorrhoeae?",options:["Гонорею","Кандидоз","Хламидиоз","Трихомониаз"],correctIndex:0,explanation:"Neisseria gonorrhoeae — возбудитель гонореи.",difficulty:"medium",tags:["заболевания","ИППП"]},{id:"obstetrics-gynecology-031",topicId:"obstetrics-gynecology",question:"Какой возбудитель вызывает кандидоз?",options:["Sarcoptes scabiei","Chlamydia trachomatis","Candida albicans","Trichomonas vaginalis"],correctIndex:2,explanation:"Candida albicans — возбудитель кандидоза.",difficulty:"easy",tags:["заболевания","инфекции"]},{id:"obstetrics-gynecology-032",topicId:"obstetrics-gynecology",question:"Что относится к гормональным нарушениям в гинекологии?",options:["Рак шейки матки","Миома матки","Синдром поликистозных яичников (СПКЯ)","Цервицит"],correctIndex:2,explanation:"Гормональные нарушения: СПКЯ, аменорея, дисфункциональные маточные кровотечения, гиперпролактинемия.",difficulty:"medium",tags:["заболевания","гормональные"]},{id:"obstetrics-gynecology-033",topicId:"obstetrics-gynecology",question:"Что относится к доброкачественным опухолям в гинекологии?",options:["Рак эндометрия","Миома матки","Гиперпролактинемия","Кольпит"],correctIndex:1,explanation:"Доброкачественные опухоли: миома матки, кисты яичников, полипы эндометрия.",difficulty:"easy",tags:["заболевания","опухоли"]},{id:"obstetrics-gynecology-034",topicId:"obstetrics-gynecology",question:"Что такое аменорея?",options:["Обильные кровотечения","Редкие менструации","Отсутствие менструации","Болезненные менструации"],correctIndex:2,explanation:"Аменорея — отсутствие менструации.",difficulty:"easy",tags:["нарушения цикла"]},{id:"obstetrics-gynecology-035",topicId:"obstetrics-gynecology",question:"Как называются редкие менструации?",options:["Олигоменорея","Полименорея","Дисменорея","Меноррагия"],correctIndex:0,explanation:"Олигоменорея — редкие менструации; полименорея — слишком частые.",difficulty:"medium",tags:["нарушения цикла"]},{id:"obstetrics-gynecology-036",topicId:"obstetrics-gynecology",question:"Что такое меноррагия?",options:["Обильные менструальные кровотечения","Слишком частые менструации","Отсутствие менструаций","Болезненные менструации"],correctIndex:0,explanation:"Меноррагия — обильные кровотечения.",difficulty:"medium",tags:["нарушения цикла"]},{id:"obstetrics-gynecology-037",topicId:"obstetrics-gynecology",question:"Как называются болезненные менструации?",options:["Дисменорея","Меноррагия","Олигоменорея","Аменорея"],correctIndex:0,explanation:"Дисменорея — болезненные менструации.",difficulty:"easy",tags:["нарушения цикла"]},{id:"obstetrics-gynecology-038",topicId:"obstetrics-gynecology",question:"Что названо в лекции фактором риска злокачественных гинекологических заболеваний?",options:["Дисменорея","Олигоменорея","Кандидоз","ВПЧ"],correctIndex:3,explanation:"Факторы риска злокачественных заболеваний: ВПЧ, наследственность, гормональные нарушения.",difficulty:"medium",tags:["заболевания","онкология"]},{id:"obstetrics-gynecology-039",topicId:"obstetrics-gynecology",question:"Какие методы диагностики злокачественных гинекологических заболеваний указаны в лекции?",options:["ПАП-тест, биопсия, онкомаркеры","Цистоскопия и ЭЭГ","Люмбальная пункция","Рентгенография позвоночника"],correctIndex:0,explanation:"Диагностика злокачественных заболеваний: ПАП-тест, биопсия, онкомаркеры.",difficulty:"medium",tags:["диагностика","онкология"]},{id:"obstetrics-gynecology-040",topicId:"obstetrics-gynecology",question:"Что указано на слайде как причина эндометриоза?",options:["Вирус папилломы человека","Гиперпролактинемия","Ретроградная менструация","Дефицит йода"],correctIndex:2,explanation:"На схеме лекции причиной эндометриоза указана ретроградная менструация.",difficulty:"hard",tags:["заболевания","эндометриоз"]},{id:"obstetrics-gynecology-041",topicId:"obstetrics-gynecology",question:"Какие факторы бесплодия названы в лекции?",options:["Только возраст","Только инфекции мочевых путей","Только мужской фактор","Трубный, гормональный, эндометриоз, мужской фактор"],correctIndex:3,explanation:"Бесплодие: трубный фактор, гормональный, эндометриоз, мужской фактор.",difficulty:"medium",tags:["бесплодие"]},{id:"obstetrics-gynecology-042",topicId:"obstetrics-gynecology",question:"Какие гинекологические зеркала упомянуты в лекции?",options:["Фолея и Нечипоренко","Симса и Фолея","Куско, Грейвса, Педерсона, Симса","Пастернацкого и Куско"],correctIndex:2,explanation:"Осмотр в зеркалах: гинекологические зеркала Куско, Грейвса, Педерсона, Симса.",difficulty:"hard",tags:["диагностика"]},{id:"obstetrics-gynecology-043",topicId:"obstetrics-gynecology",question:"Какой лабораторный метод в гинекологии является цитологическим исследованием?",options:["Мазок на флору","ПАП-тест","ПЦР на инфекции","Гормональный анализ крови"],correctIndex:1,explanation:"ПАП-тест — цитологическое исследование.",difficulty:"medium",tags:["диагностика"]},{id:"obstetrics-gynecology-044",topicId:"obstetrics-gynecology",question:"Какой из перечисленных методов относится к инструментальным методам диагностики в гинекологии?",options:["Мазок на флору","ПЦР на инфекции","ПАП-тест","Кольпоскопия"],correctIndex:3,explanation:"Инструментальные методы: УЗИ органов малого таза, кольпоскопия, гистероскопия, лапароскопия, маммография.",difficulty:"medium",tags:["диагностика"]},{id:"obstetrics-gynecology-045",topicId:"obstetrics-gynecology",question:"Как называется операция удаления матки?",options:["Гистерэктомия","Лапароскопия","Кистэктомия","Миомэктомия"],correctIndex:0,explanation:"Гистерэктомия — удаление матки.",difficulty:"easy",tags:["лечение","хирургия"]},{id:"obstetrics-gynecology-046",topicId:"obstetrics-gynecology",question:"Как называется удаление миом?",options:["Миомэктомия","Гистерэктомия","Нефрэктомия","Кистэктомия"],correctIndex:0,explanation:"Хирургическое лечение: удаление кист (кистэктомия) и миом (миомэктомия).",difficulty:"medium",tags:["лечение","хирургия"]},{id:"obstetrics-gynecology-047",topicId:"obstetrics-gynecology",question:"К какой группе методов лечения относится ЭКО?",options:["К хирургическим методам удаления опухолей","К медикаментозным методам","К методам диагностики","К вспомогательным репродуктивным технологиям"],correctIndex:3,explanation:"Вспомогательные методы — репродуктивные технологии (ЭКО).",difficulty:"medium",tags:["лечение"]},{id:"obstetrics-gynecology-048",topicId:"obstetrics-gynecology",question:"С какого этапа начинается процедура ЭКО по схеме лекции?",options:["С подготовки спермы","С имплантации эмбриона","С оплодотворения яйцеклетки","С овариальной стимуляции"],correctIndex:3,explanation:"Этапы ЭКО по схеме: 1 — овариальная стимуляция, 2 — забор яйцеклетки, 3 — подготовка спермы, 4 — оплодотворение, 5 — развитие эмбриона, 6 — имплантация.",difficulty:"hard",tags:["лечение","ЭКО"]}];export{o as default};
